package com.hms.ui;
import com.hms.model.User; import com.hms.service.AuthService; import com.hms.util.UiUtil; import javax.swing.*; import java.awt.*;
public class LoginFrame extends JFrame { private final AuthService auth; private final JTextField username=new JTextField("admin"); private final JPasswordField password=new JPasswordField("admin123"); public LoginFrame(AuthService a){auth=a;setTitle("Hospital Management System - Login");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(420,260);setLocationRelativeTo(null);JPanel p=UiUtil.formPanel();GridBagConstraints c=new GridBagConstraints();c.insets=new Insets(6,6,6,6);c.anchor=GridBagConstraints.WEST;UiUtil.addField(p,c,0,"Username",username);UiUtil.addField(p,c,1,"Password",password);JButton b=new JButton("Sign in");b.addActionListener(e->login());c.gridx=1;c.gridy=2;c.fill=GridBagConstraints.NONE;p.add(b,c);add(p);}
 private void login(){try{User u=auth.login(username.getText(),new String(password.getPassword()));if(u==null){JOptionPane.showMessageDialog(this,"Invalid username or password.","Login failed",JOptionPane.ERROR_MESSAGE);return;}dispose();new MainFrame(u).setVisible(true);}catch(Exception e){UiUtil.showError(this,e);}}
}
